def scrape_webpage(profile_id, url, wait_for=None, include_html=None, include_screenshot=None, **_extra):
    import json, os, datetime, time, re, uuid
    from urllib.parse import urlparse

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0163000" if __import__("os").path.isdir("./environment_mix/0163000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_uri(u):
        try:
            p = urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _gen_id(prefix):
        return f"{prefix}{uuid.uuid4().hex}"

    # ---- validate inputs (types/ranges/patterns) ----
    if not isinstance(profile_id, str) or not re.match(r"^hbp_prof_[0-9A-HJKMNP-TV-Z]{10,}$", profile_id or ""):
        return _err("VALIDATION_ERROR", "profile_id must be a valid Hyperbrowser profile ULID.")
    if not isinstance(url, str) or not _is_uri(url):
        return _err("VALIDATION_ERROR", "url must be a valid URI (http/https).")
    if wait_for is not None:
        if not isinstance(wait_for, int):
            return _err("VALIDATION_ERROR", "wait_for must be an integer.")
        if wait_for < 0:
            return _err("VALIDATION_ERROR", "wait_for must be >= 0.")
    if include_html is not None and not isinstance(include_html, bool):
        return _err("VALIDATION_ERROR", "include_html must be a boolean.")
    if include_screenshot is not None and not isinstance(include_screenshot, bool):
        return _err("VALIDATION_ERROR", "include_screenshot must be a boolean.")

    include_html = bool(include_html) if include_html is not None else False
    include_screenshot = bool(include_screenshot) if include_screenshot is not None else False

    profiles = _load("profiles.json")
    jobs = _load("jobs.json")
    web_pages = _load("web_pages.json")

    # ---- enforce profile exists and attachable ----
    prof = next((p for p in profiles if p.get("profile_id") == profile_id), None)
    if not prof:
        return _err("NOT_FOUND", "profile_id not found.")
    if prof.get("status") != "active":
        return _err("INVALID_TRANSITION", "profile is not attachable to new jobs because it is not active.", status=prof.get("status"))

    now = _now()

    # ---- create job row (required for every invocation) ----
    job_id = _gen_id("hbp_job_")
    job_row = {
        "job_id": job_id,
        "tool_name": "scrape_webpage",
        "profile_id": profile_id,
        "status": "running",
        "input": {
            "profile_id": profile_id,
            "url": url,
            "wait_for": wait_for if wait_for is not None else 0,
            "include_html": include_html,
            "include_screenshot": include_screenshot,
        },
        "output": None,
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": None,
        "cost_usd": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job_row)

    # ---- simulate fetch + create at least one web_pages row ----
    # Respect unique(job_id,url) constraint.
    if any(wp.get("job_id") == job_id and wp.get("url") == url for wp in web_pages):
        # Should never happen since job_id is new, but enforce.
        job_row["status"] = "failed"
        job_row["error_code"] = "CONFLICT"
        job_row["error_message"] = "Duplicate (job_id,url) page record."
        job_row["finished_at"] = _now()
        job_row["updated_at"] = job_row["finished_at"]
        _save("jobs.json", jobs)
        return _err("CONFLICT", "unique(job_id,url) violated for web_pages.", job_id=job_id, url=url)

    fetched_at = _now()
    page_id = _gen_id("hbp_page_")
    html_key = f"obj/html/{page_id}.html" if include_html else None
    screenshot_key = f"obj/screenshot/{page_id}.png" if include_screenshot else None

    # naive "success" heuristic: valid URI -> 200
    http_status = 200
    content_type = "text/html; charset=utf-8"
    title = None
    text_content = None

    wp_row = {
        "page_id": page_id,
        "job_id": job_id,
        "url": url,
        "canonical_url": None,
        "http_status": http_status,
        "content_type": content_type,
        "title": title,
        "text_content": text_content,
        "html_storage_key": html_key,
        "screenshot_storage_key": screenshot_key,
        "fetched_at": fetched_at,
        "created_at": fetched_at,
        "updated_at": fetched_at,
    }
    web_pages.append(wp_row)

    # ---- mark job succeeded (legal transition running->succeeded) ----
    finished = _now()
    job_row["status"] = "succeeded"
    job_row["finished_at"] = finished
    job_row["updated_at"] = finished

    # cost model: base + per-second wait
    wf_ms = job_row["input"]["wait_for"]
    job_row["cost_usd"] = max(0.0, round(0.001 + (wf_ms / 1000.0) * 0.0001 + (0.0002 if include_screenshot else 0.0), 6))

    job_row["output"] = {
        "job_id": job_id,
        "page": {
            "page_id": page_id,
            "url": url,
            "http_status": http_status,
            "content_type": content_type,
            "html_storage_key": html_key,
            "screenshot_storage_key": screenshot_key,
            "fetched_at": fetched_at,
        },
    }

    # update profile last_used_at
    prof["last_used_at"] = finished
    prof["updated_at"] = finished

    _save("profiles.json", profiles)
    _save("web_pages.json", web_pages)
    _save("jobs.json", jobs)

    return {
        "job": job_row,
        "page": wp_row,
        "latency_ms": int((time.time() - _t0) * 1000),
    }

def crawl_webpages(profile_id, start_url, max_pages=None, max_depth=None, same_domain_only=None, include_html=None, include_screenshot=None, **_extra):
    import json, os, datetime, time, re, uuid
    from urllib.parse import urlparse, urljoin

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0163000" if __import__("os").path.isdir("./environment_mix/0163000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_uri(u):
        try:
            p = urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _gen_id(prefix):
        return f"{prefix}{uuid.uuid4().hex}"

    # ---- validate ----
    if not isinstance(profile_id, str) or not re.match(r"^hbp_prof_[0-9A-HJKMNP-TV-Z]{10,}$", profile_id or ""):
        return _err("VALIDATION_ERROR", "profile_id must be a valid Hyperbrowser profile ULID.")
    if not isinstance(start_url, str) or not _is_uri(start_url):
        return _err("VALIDATION_ERROR", "start_url must be a valid URI (http/https).")

    if max_pages is not None:
        if not isinstance(max_pages, int):
            return _err("VALIDATION_ERROR", "max_pages must be an integer.")
        if max_pages < 1:
            return _err("VALIDATION_ERROR", "max_pages must be >= 1.")
    if max_depth is not None:
        if not isinstance(max_depth, int):
            return _err("VALIDATION_ERROR", "max_depth must be an integer.")
        if max_depth < 0:
            return _err("VALIDATION_ERROR", "max_depth must be >= 0.")

    if same_domain_only is not None and not isinstance(same_domain_only, bool):
        return _err("VALIDATION_ERROR", "same_domain_only must be a boolean.")
    if include_html is not None and not isinstance(include_html, bool):
        return _err("VALIDATION_ERROR", "include_html must be a boolean.")
    if include_screenshot is not None and not isinstance(include_screenshot, bool):
        return _err("VALIDATION_ERROR", "include_screenshot must be a boolean.")

    max_pages = max_pages if max_pages is not None else 10
    max_depth = max_depth if max_depth is not None else 1
    same_domain_only = bool(same_domain_only) if same_domain_only is not None else True
    include_html = bool(include_html) if include_html is not None else False
    include_screenshot = bool(include_screenshot) if include_screenshot is not None else False

    profiles = _load("profiles.json")
    jobs = _load("jobs.json")
    web_pages = _load("web_pages.json")

    prof = next((p for p in profiles if p.get("profile_id") == profile_id), None)
    if not prof:
        return _err("NOT_FOUND", "profile_id not found.")
    if prof.get("status") != "active":
        return _err("INVALID_TRANSITION", "profile is not attachable to new jobs because it is not active.", status=prof.get("status"))

    now = _now()
    job_id = _gen_id("hbp_job_")
    job_row = {
        "job_id": job_id,
        "tool_name": "crawl_webpages",
        "profile_id": profile_id,
        "status": "running",
        "input": {
            "profile_id": profile_id,
            "start_url": start_url,
            "max_pages": max_pages,
            "max_depth": max_depth,
            "same_domain_only": same_domain_only,
            "include_html": include_html,
            "include_screenshot": include_screenshot,
        },
        "output": None,
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": None,
        "cost_usd": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job_row)

    # ---- crawl simulation: generate deterministic set of URLs ----
    start_p = urlparse(start_url)
    base = f"{start_p.scheme}://{start_p.netloc}"
    seed_path = start_p.path if start_p.path else "/"

    # BFS queue: (url, depth)
    queue = [(start_url, 0)]
    seen = set([start_url])
    fetched_pages = []

    def _allowed(u):
        if not _is_uri(u):
            return False
        if not same_domain_only:
            return True
        up = urlparse(u)
        return up.netloc == start_p.netloc and up.scheme in ("http", "https")

    # Create "discovered" URLs by appending /d{depth}/p{i}
    while queue and len(fetched_pages) < max_pages:
        cur, d = queue.pop(0)
        # fetch cur successfully
        fetched_pages.append((cur, d))
        if d >= max_depth:
            continue
        # discover up to 2 children
        for i in range(1, 3):
            child = urljoin(base, f"{seed_path.rstrip('/')}/d{d+1}/p{i}")
            if child not in seen and _allowed(child):
                seen.add(child)
                queue.append((child, d + 1))
        # also discover a cross-domain link that may be filtered
        cross = f"{start_p.scheme}://example.com{seed_path.rstrip('/')}/x{d+1}"
        if cross not in seen and _allowed(cross):
            seen.add(cross)
            queue.append((cross, d + 1))

    # ---- persist web_pages rows; enforce unique(job_id,url) ----
    created = 0
    for u, d in fetched_pages:
        if any(wp.get("job_id") == job_id and wp.get("url") == u for wp in web_pages):
            # skip duplicates to enforce unique(job_id,url) during crawling
            continue
        fetched_at = _now()
        page_id = _gen_id("hbp_page_")
        wp_row = {
            "page_id": page_id,
            "job_id": job_id,
            "url": u,
            "canonical_url": None,
            "http_status": 200,
            "content_type": "text/html; charset=utf-8",
            "title": None,
            "text_content": None,
            "html_storage_key": (f"obj/html/{page_id}.html" if include_html else None),
            "screenshot_storage_key": (f"obj/screenshot/{page_id}.png" if include_screenshot else None),
            "fetched_at": fetched_at,
            "created_at": fetched_at,
            "updated_at": fetched_at,
        }
        web_pages.append(wp_row)
        created += 1

    finished = _now()
    job_row["status"] = "succeeded"
    job_row["finished_at"] = finished
    job_row["updated_at"] = finished

    # cost: per page
    job_row["cost_usd"] = max(0.0, round(0.002 + created * (0.0005 + (0.0002 if include_screenshot else 0.0)), 6))
    job_row["output"] = {
        "job_id": job_id,
        "start_url": start_url,
        "pages_fetched": created,
        "page_ids": [wp["page_id"] for wp in web_pages if wp.get("job_id") == job_id],
    }

    prof["last_used_at"] = finished
    prof["updated_at"] = finished

    _save("profiles.json", profiles)
    _save("web_pages.json", web_pages)
    _save("jobs.json", jobs)

    return {
        "job": job_row,
        "summary": job_row["output"],
        "latency_ms": int((time.time() - _t0) * 1000),
    }

