    # ---- validate ----
    if not isinstance(profile_id, str) or not re.match(r"^hbp_prof_[0-9A-HJKMNP-TV-Z]{10,}$", profile_id or ""):
        return _err("VALIDATION_ERROR", "profile_id must be a valid Hyperbrowser profile ULID.")
    if not isinstance(url, str) or not _is_uri(url):
        return _err("VALIDATION_ERROR", "url must be a valid URI (http/https).")
    if not isinstance(schema, dict):
        return _err("VALIDATION_ERROR", "schema must be an object.")
    if wait_for is not None:
        if not isinstance(wait_for, int):
            return _err("VALIDATION_ERROR", "wait_for must be an integer.")
        if wait_for < 0:
            return _err("VALIDATION_ERROR", "wait_for must be >= 0.")

    profiles = _load("profiles.json")
    jobs = _load("jobs.json")
    web_pages = _load("web_pages.json")

    prof = next((p for p in profiles if p.get("profile_id") == profile_id), None)
    if not prof:
        return _err("NOT_FOUND", "profile_id not found.")
    if prof.get("status") != "active":
        return _err("INVALID_TRANSITION", "profile is not attachable to new jobs because it is not active.", status=prof.get("status"))

    now = _now()
    job_id = _gen_id("hbp_job_")
    job_row = {
        "job_id": job_id,
        "tool_name": "extract_structured_data",
        "profile_id": profile_id,
        "status": "running",
        "input": {
            "profile_id": profile_id,
            "url": url,
            "schema": schema,
            "wait_for": wait_for if wait_for is not None else 0,
        },
        "output": None,
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": None,
        "cost_usd": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job_row)

    # create a page snapshot for provenance (even if extraction is the main artifact)
    fetched_at = _now()
    page_id = _gen_id("hbp_page_")
    if any(wp.get("job_id") == job_id and wp.get("url") == url for wp in web_pages):
        job_row["status"] = "failed"
        job_row["error_code"] = "CONFLICT"
        job_row["error_message"] = "Duplicate (job_id,url) page record."
        job_row["finished_at"] = _now()
        job_row["updated_at"] = job_row["finished_at"]
        _save("jobs.json", jobs)
        return _err("CONFLICT", "unique(job_id,url) violated for web_pages.", job_id=job_id, url=url)

    wp_row = {
        "page_id": page_id,
        "job_id": job_id,
        "url": url,
        "canonical_url": None,
        "http_status": 200,
        "content_type": "text/html; charset=utf-8",
        "title": None,
        "text_content": None,
        "html_storage_key": None,
        "screenshot_storage_key": None,
        "fetched_at": fetched_at,
        "created_at": fetched_at,
        "updated_at": fetched_at,
    }
    web_pages.append(wp_row)

    # ---- produce extracted JSON compatible with schema (best-effort) ----
    # We keep it simple: if schema has "properties", return keys with null; else echo schema shape marker.
    extracted = {}
    props = schema.get("properties") if isinstance(schema.get("properties"), dict) else None
    if props:
        for k, spec in props.items():
            t = spec.get("type") if isinstance(spec, dict) else None
            if t == "string":
                extracted[k] = ""
            elif t == "number":
                extracted[k] = 0
            elif t == "integer":
                extracted[k] = 0
            elif t == "boolean":
                extracted[k] = False
            elif t == "array":
                extracted[k] = []
            elif t == "object":
                extracted[k] = {}
            else:
                extracted[k] = None
    else:
        extracted = {"_extracted": True}

    finished = _now()
    job_row["status"] = "succeeded"
    job_row["finished_at"] = finished
    job_row["updated_at"] = finished
    wf_ms = job_row["input"]["wait_for"]
    job_row["cost_usd"] = max(0.0, round(0.002 + (wf_ms / 1000.0) * 0.0001, 6))
    job_row["output"] = {
        "job_id": job_id,
        "page_id": page_id,
        "url": url,
        "extracted": extracted,
    }

    prof["last_used_at"] = finished
    prof["updated_at"] = finished

    _save("profiles.json", profiles)
    _save("web_pages.json", web_pages)
    _save("jobs.json", jobs)

    return {
        "job": job_row,
        "page": wp_row,
        "result": extracted,
        "latency_ms": int((time.time() - _t0) * 1000),
    }

def browser_use_agent(profile_id, instructions, start_url=None, **_extra):
    import json, os, datetime, time, re, uuid
    from urllib.parse import urlparse

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0163000" if __import__("os").path.isdir("./environment_mix/0163000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_uri(u):
        try:
            p = urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _gen_id(prefix):
        return f"{prefix}{uuid.uuid4().hex}"

    # ---- validate ----
    if not isinstance(profile_id, str) or not re.match(r"^hbp_prof_[0-9A-HJKMNP-TV-Z]{10,}$", profile_id or ""):
        return _err("VALIDATION_ERROR", "profile_id must be a valid Hyperbrowser profile ULID.")
    if not isinstance(instructions, str) or not instructions.strip():
        return _err("VALIDATION_ERROR", "instructions must be a non-empty string.")
    if start_url is not None:
        if not isinstance(start_url, str) or not _is_uri(start_url):
            return _err("VALIDATION_ERROR", "start_url must be a valid URI (http/https) when provided.")

    profiles = _load("profiles.json")
    jobs = _load("jobs.json")
    agent_sessions = _load("agent_sessions.json")

    prof = next((p for p in profiles if p.get("profile_id") == profile_id), None)
    if not prof:
        return _err("NOT_FOUND", "profile_id not found.")
    if prof.get("status") != "active":
        return _err("INVALID_TRANSITION", "profile is not attachable to new jobs because it is not active.", status=prof.get("status"))

    now = _now()
    job_id = _gen_id("hbp_job_")
    job_row = {
        "job_id": job_id,
        "tool_name": "browser_use_agent",
        "profile_id": profile_id,
        "status": "running",
        "input": {
            "profile_id": profile_id,
            "instructions": instructions,
            "start_url": start_url,
        },
        "output": None,
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": None,
        "cost_usd": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job_row)

    # agent_sessions must have unique(job_id)
    if any(s.get("job_id") == job_id for s in agent_sessions):
        job_row["status"] = "failed"
        job_row["error_code"] = "CONFLICT"
        job_row["error_message"] = "unique(job_id) violated for agent_sessions."
        job_row["finished_at"] = _now()
        job_row["updated_at"] = job_row["finished_at"]
        _save("jobs.json", jobs)
        return _err("CONFLICT", "unique(job_id) violated for agent_sessions.", job_id=job_id)

    session_id = _gen_id("hbp_sess_")
    sess_now = _now()
    session_row = {
        "session_id": session_id,
        "job_id": job_id,
        "agent_type": "browser_use",
        "instructions": instructions,
        "transcript_storage_key": None,
        "final_url": None,
        "created_at": sess_now,
        "updated_at": sess_now,
    }
    agent_sessions.append(session_row)

    # succeed and set transcript_storage_key as required
    finished = _now()
    transcript_key = f"obj/transcripts/{session_id}.jsonl"
    final_url = start_url if start_url is not None else "about:blank"

    session_row["transcript_storage_key"] = transcript_key
    session_row["final_url"] = final_url
    session_row["updated_at"] = finished

    job_row["status"] = "succeeded"
    job_row["finished_at"] = finished
    job_row["updated_at"] = finished
    # cost based on instruction length (token-ish)
    job_row["cost_usd"] = max(0.0, round(0.003 + (len(instructions) / 1000.0) * 0.001, 6))
    job_row["output"] = {
        "job_id": job_id,
        "session_id": session_id,
        "final_url": final_url,
        "transcript_storage_key": transcript_key,
    }

    prof["last_used_at"] = finished
    prof["updated_at"] = finished

    _save("profiles.json", profiles)
    _save("agent_sessions.json", agent_sessions)
    _save("jobs.json", jobs)

    return {
        "job": job_row,
        "session": session_row,
        "latency_ms": int((time.time() - _t0) * 1000),
    }

def claude_computer_use_agent(profile_id, instructions, start_url=None, **_extra):
    import json, os, datetime, time, re, uuid, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0163000" if __import__("os").path.isdir("./environment_mix/0163000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    profiles = _load("profiles.json")
    jobs = _load("jobs.json")
    sessions = _load("agent_sessions.json")
    web_pages = _load("web_pages.json")

    if not isinstance(profile_id, str) or not re.match(r"^hbp_prof_[0-9A-HJKMNP-TV-Z]{10,}$", profile_id):
        return _err("VALIDATION_ERROR", "profile_id is invalid.")
    if not isinstance(instructions, str) or not instructions.strip():
        return _err("VALIDATION_ERROR", "instructions is required and must be a non-empty string.")
    if start_url is not None:
        if not isinstance(start_url, str) or not start_url.strip():
            return _err("VALIDATION_ERROR", "start_url must be a non-empty string when provided.")
        try:
            u = urllib.parse.urlparse(start_url)
            if u.scheme not in ("http", "https") or not u.netloc:
                return _err("VALIDATION_ERROR", "start_url must be an absolute http(s) URL.")
        except Exception:
            return _err("VALIDATION_ERROR", "start_url must be a valid URI.")

    prof = next((p for p in profiles if p.get("profile_id") == profile_id), None)
    if not prof:
        return _err("NOT_FOUND", "Profile not found.", profile_id=profile_id)
    if prof.get("status") != "active":
        return _err("INVALID_TRANSITION", "Profile is not attachable to new jobs (must be active).", profile_status=prof.get("status"))

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        rnd = uuid.uuid4().int
        chars = []
        x = (ts << 80) | (rnd & ((1 << 80) - 1))
        for _ in range(26):
            chars.append(alphabet[x & 31])
            x >>= 5
        return prefix + "".join(reversed(chars))

    job_id = _new_id("hbp_job_")
    job = {
        "job_id": job_id,
        "tool_name": "claude_computer_use_agent",
        "profile_id": profile_id,
        "status": "queued",
        "input": {"profile_id": profile_id, "instructions": instructions, "start_url": start_url},
        "output": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "cost_usd": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    if any(j.get("job_id") == job_id for j in jobs):
        return _err("CONFLICT", "Generated job_id collided; retry.")
    jobs.append(job)

    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    job["status"] = "running"
    job["started_at"] = started
    job["updated_at"] = started

    if any(s.get("job_id") == job_id for s in sessions):
        job["status"] = "failed"
        job["error_code"] = "CONFLICT"
        job["error_message"] = "Agent session already exists for this job."
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        job["finished_at"] = finished
        job["updated_at"] = finished
        _save("jobs.json", jobs)
        return _err("CONFLICT", "Agent session already exists for this job.", job_id=job_id)

    session_id = _new_id("hbp_sess_")
    sess = {
        "session_id": session_id,
        "job_id": job_id,
        "agent_type": "claude_computer_use",
        "instructions": instructions,
        "transcript_storage_key": None,
        "final_url": None,
        "created_at": started,
        "updated_at": started,
    }
    sessions.append(sess)

    final_url = start_url if start_url else None
    transcript_key = f"hbp_obj_transcript_{session_id}.jsonl"
    sess["transcript_storage_key"] = transcript_key
    sess["final_url"] = final_url
    sess["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    prof["last_used_at"] = sess["updated_at"]
    prof["updated_at"] = sess["updated_at"]

    # Cost heuristic slightly higher for "complex reasoning"
    cost = 0.02 + min(0.35, max(0.0, (len(instructions) / 4000.0) * 0.15))
    job["cost_usd"] = float(max(0.0, round(cost, 6)))

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    job["status"] = "succeeded"
    job["finished_at"] = finished
    job["updated_at"] = finished
    job["output"] = {
        "session_id": session_id,
        "final_url": final_url,
        "transcript_storage_key": transcript_key,
        "job_id": job_id,
    }

    _save("profiles.json", profiles)
    _save("agent_sessions.json", sessions)
    _save("web_pages.json", web_pages)
    _save("jobs.json", jobs)

    return {
        "job": job,
        "session": sess,
    }

