    # Quota: maximum number of non-deleted profiles (service-level quota since no account table exists)
    MAX_PROFILES = 100
    activeish = [p for p in profiles if p.get("status") in ("active", "deleting")]
    if len(activeish) >= MAX_PROFILES:
        return _err("QUOTA_EXCEEDED", "Maximum number of profiles reached.", max_profiles=MAX_PROFILES)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        rnd = uuid.uuid4().int
        chars = []
        x = (ts << 80) | (rnd & ((1 << 80) - 1))
        for _ in range(26):
            chars.append(alphabet[x & 31])
            x >>= 5
        return prefix + "".join(reversed(chars))

    profile_id = _new_id("hbp_prof_")
    if any(p.get("profile_id") == profile_id for p in profiles):
        return _err("CONFLICT", "Generated profile_id collided; retry.")

    # Create profile row
    prof = {
        "profile_id": profile_id,
        "display_name": display_name.strip(),
