    # Create corresponding job row (must exist and be succeeded)
    job_id = _new_id("hbp_job_")
    if any(j.get("job_id") == job_id for j in jobs):
        return _err("CONFLICT", "Generated job_id collided; retry.")

    job = {
        "job_id": job_id,
        "tool_name": "create_profile",
        "profile_id": None,
        "status": "succeeded",
        "input": {"display_name": display_name.strip()},
        "output": {"profile_id": profile_id},
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "cost_usd": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)

    _save("profiles.json", profiles)
    _save("jobs.json", jobs)

    return {
        "profile": prof,
        "job": job,
    }

def list_profiles(limit=None, cursor=None, status=None, order=None, **_extra):
    import json, os, datetime, time, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0163000" if __import__("os").path.isdir("./environment_mix/0163000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulidish(prefix):
        # Not a true ULID, but matches the datastore pattern constraints loosely.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        for _ in range(16):
            out.append(alphabet[secrets.randbelow(32)])
        return prefix + "".join(reversed(out))

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        # Cursor is "opaque". Accept either:
        # - our own base64url JSON cursor
        # - a raw profile_id (common in simple pagination)
        if cur is None:
            return None
        if not isinstance(cur, str):
            return "MALFORMED"
        if cur == "":
            return "MALFORMED"
        # raw profile id passthrough
        if cur.startswith("hbp_prof_"):
            return {"after_profile_id": cur}
        # try base64url JSON
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "MALFORMED"
            return obj
        except Exception:
            return "MALFORMED"

    # request logging (if present)
    has_reqlog = os.path.exists(os.path.join(_DB, "request_logs.json"))
    request_logs = _load("request_logs.json") if has_reqlog else None
    def _log(status, error_code=None):
        if not has_reqlog:
            return
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "request_id": _ulidish("hbp_req_"),
            "endpoint": "list_profiles",
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _utcnow_z()
        })
        _save("request_logs.json", request_logs)

    profiles = _load("profiles.json")
    jobs = _load("jobs.json")

    # Validate
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    allowed_status = {"active", "deleting", "deleted"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deleting, deleted.", field="status")

    allowed_order = {"created_at", "-created_at", "updated_at", "-updated_at", "last_used_at", "-last_used_at"}
    if order is None:
        order = "created_at"
    if not isinstance(order, str) or order not in allowed_order:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order must be one of: created_at, -created_at, updated_at, -updated_at, last_used_at, -last_used_at.", field="order")

    cur_obj = _decode_cursor(cursor)
    if cur_obj == "MALFORMED":
        # Relaxed behavior: cursor is opaque; only reject non-string/empty or unparseable values.
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor is malformed.", field="cursor")

    # Default listing excludes deleted unless explicitly requested
    if status is None:
        filtered = [p for p in profiles if p.get("status") in ("active", "deleting")]
    else:
        filtered = [p for p in profiles if p.get("status") == status]

    sort_field = order[1:] if order.startswith("-") else order
    reverse = order.startswith("-")

    def _sort_key(p):
        # None-safe ordering: None sorts last for asc, first for desc (common API behavior)
        v = p.get(sort_field)
        dt = _parse_dt(v) if sort_field in ("created_at", "updated_at", "last_used_at") else None
        if dt is not None:
            # Convert to timestamp number for stable sort
            val = dt.timestamp()
        else:
            val = v
        is_none = (val is None)
        # tuple ensures deterministic ordering with profile_id as tiebreaker
        if reverse:
            return (0 if is_none else 1, val, p.get("profile_id") or "")
        return (1 if is_none else 0, val, p.get("profile_id") or "")

    filtered.sort(key=_sort_key, reverse=reverse)

    # Apply cursor as "start after" semantics.
    start_idx = 0
    if isinstance(cur_obj, dict):
        after_id = cur_obj.get("after_profile_id")
        if isinstance(after_id, str):
            for i, p in enumerate(filtered):
                if p.get("profile_id") == after_id:
                    start_idx = i + 1
                    break

    page = filtered[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(filtered)
    next_cursor = None
    if has_more and page:
        next_cursor = page[-1].get("profile_id")

    # Create exactly one jobs row for this tool invocation
    now = _utcnow_z()
    job_id = _ulidish("hbp_job_")
    job_row = {
        "job_id": job_id,
        "tool_name": "list_profiles",
        "profile_id": None,
        "status": "succeeded",
        "input": {"limit": limit, "cursor": cursor, "status": status, "order": order},
        "output": {
            "profiles": page,
            "total": len(filtered),
            "has_more": has_more,
            "next_cursor": next_cursor
        },
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "cost_usd": 0,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job_row)
    _save("jobs.json", jobs)

    _log("ok", None)
    return {"profiles": page, "total": len(filtered), "has_more": has_more, "next_cursor": next_cursor}

def cancel_job(job_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0163000" if __import__("os").path.isdir("./environment_mix/0163000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, error_code=None):
        # Only if the deployment has a request log collection.
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        rid = "hbp_req_" + str(int(time.time() * 1000)) + "_" + str(len(logs) + 1)
        logs.append({
            "request_id": rid,
            "endpoint": "cancel_job",
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _utcnow_z()
        })
        _save("request_logs.json", logs)

    # Validate inputs first
    if not isinstance(job_id, str):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "job_id must be a string.", field="job_id")
    if re.match(r"^hbp_job_[0-9A-HJKMNP-TV-Z]{10,}$", job_id) is None:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "job_id does not match required pattern.", field="job_id")

    jobs = _load("jobs.json")
    if not isinstance(jobs, list):
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Jobs datastore is unavailable or invalid.")

    job_idx = None
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("job_id") == job_id:
            job_idx = i
            break
    if job_idx is None:
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Job not found.", job_id=job_id)

    job = jobs[job_idx]
    status = job.get("status")
    allowed_statuses = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status not in allowed_statuses:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Job status is invalid in datastore.", field="status", job_id=job_id)

    # Enforce lifecycle transitions: queued->cancelled, running->cancelled
    transitions = {
        "queued": ["running", "cancelled", "failed"],
        "running": ["succeeded", "failed", "cancelled"],
        "succeeded": [],
        "failed": [],
        "cancelled": []
    }

    # Terminal-state conflict
    if status in ("succeeded", "failed", "cancelled"):
        _append_request_log("error", "CONFLICT")
        return _err("CONFLICT", "Job is already in a terminal state and cannot be cancelled.", job_id=job_id, status=status)

    if "cancelled" not in transitions.get(status, []):
        _append_request_log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Job cannot transition to cancelled from its current status.", job_id=job_id, from_status=status, to_status="cancelled")

    # Apply mutation (NO SUCCESS WITHOUT EFFECT)
    now = _utcnow_z()
    job["status"] = "cancelled"
    job["updated_at"] = now
    job["finished_at"] = now
    if job.get("started_at") is None:
        job["started_at"] = now
    # Cost must be present and >=0; keep existing if valid, else set to 0 for cancellation.
    cost = job.get("cost_usd")
    if not isinstance(cost, (int, float)) or cost < 0:
        job["cost_usd"] = 0.0

    jobs[job_idx] = job
    _save("jobs.json", jobs)

    _append_request_log("ok", None)
    return {"job": job}
